package com.trampolim.api.education;

import java.util.*;import java.time.*;import java.security.SecureRandom;
import static com.trampolim.api.radar.RadarModel.*;
import com.trampolim.api.radar.RadarBridge;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.http.HttpStatus;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;

@Service
@ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class PassportService {
 private final JdbcTemplate jdbc;private final LearningAccess access;private final RadarBridge bridge;private final PassportOutbox outbox;
 public PassportService(@Qualifier("capacitaJdbcTemplate")JdbcTemplate jdbc,LearningAccess access,RadarBridge bridge,PassportOutbox outbox){this.jdbc=jdbc;this.access=access;this.bridge=bridge;this.outbox=outbox;}
 public record Share(List<UUID> credentials,String recipientEmail,String holderLabel,int expiresInDays,boolean consent){}
 public record Verify(String token,String recipientEmail){}
 public record Revocation(String reason){}
 private String select(){return "SELECT a.*,u.full_name AS student_name, (t.status='SUBMITTED' AND t.passed=TRUE AND t.assessment_id=a.assessment_id AND t.student_id=a.student_id AND t.score_percent=a.score_percent) AS evidence_valid FROM learning_competency_awards a JOIN learning_assessment_attempts t ON t.id=a.attempt_id JOIN student_users u ON u.id=a.student_id AND u.account_status='ACTIVE' AND u.email_verified=TRUE";}
 public String status(Map<String,Object> row){if(row.get("revoked_at")!=null)return "REVOKED";if(row.get("valid_until")!=null&&!((java.sql.Timestamp)row.get("valid_until")).toInstant().isAfter(Instant.now()))return "EXPIRED";return Boolean.TRUE.equals(row.get("evidence_valid"))?"ACTIVE":"EVIDENCE_INVALID";}
 private Map<String,Object> details(Map<String,Object> row,boolean evidence){var result=new LinkedHashMap<String,Object>();result.put("id",row.get("id"));result.put("status",status(row));result.put("issuer",row.get("issuer_name"));result.put("issuedAt",row.get("awarded_at"));result.put("validUntil",row.get("valid_until"));result.put("recordType","INTERNAL_VERIFIED_LEARNING_COMPETENCY");result.put("formalCertificate",false);if(evidence)for(String key:List.of("name","description","course_title","module_title","teacher_name","criterion","skill_code","skill_level"))result.put(key,row.get(key));return result;}
 public Map<String,Object> credentials(String email,int offset,int limit){long uid=access.account(email).id();page(offset,limit);var rows=jdbc.queryForList(select()+" WHERE a.student_id=? ORDER BY a.awarded_at DESC,a.id LIMIT ? OFFSET ?",uid,limit+1,offset);return Map.of("items",rows.stream().limit(limit).map(r->details(r,true)).toList(),"hasMore",rows.size()>limit);}
 public List<Map<String,Object>> issued(String email,long course){var user=access.teacher(email);access.ownCourse(user,course);return jdbc.queryForList(select()+" WHERE a.course_id=? ORDER BY a.awarded_at DESC LIMIT 100",course).stream().map(r->{var value=details(r,true);value.put("studentName",r.get("student_name"));return value;}).toList();}
 public Map<String,Object> verification(UUID id){var rows=jdbc.queryForList(select()+" WHERE a.id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Registro não localizado ou indisponível.");return details(rows.get(0),false);}
 @Transactional("capacitaTransactionManager")public void revokeCredential(String email,UUID id,Revocation input){var user=access.teacher(email);var row=jdbc.queryForList("SELECT course_id,revoked_at FROM learning_competency_awards WHERE id=? FOR UPDATE",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));access.ownCourse(user,((Number)row.get("course_id")).longValue());if(input==null||text(input.reason(),500).length()<10)bad("Registre uma justificativa de ao menos dez caracteres. Revogação da credencial é definitiva.");if(row.get("revoked_at")!=null)return;jdbc.update("UPDATE learning_competency_awards SET revoked_at=CURRENT_TIMESTAMP,revocation_reason=?,share_hash=NULL,share_expires_at=NULL WHERE id=?",input.reason().trim(),id);outbox.invalidateAward(id);audit(user.id(),id,"CREDENTIAL_REVOKED");}
 public List<Map<String,Object>> shares(String email){return jdbc.queryForList("SELECT id,recipient_email,holder_label,consent_at,expires_at,revoked_at FROM learning_passport_shares WHERE student_id=? ORDER BY (revoked_at IS NULL AND expires_at>CURRENT_TIMESTAMP) DESC,consent_at DESC LIMIT 100",access.account(email).id());}
 @Transactional("capacitaTransactionManager")public Map<String,Object> share(String email,Share input){long uid=access.account(email).id();if(input==null||!input.consent()||input.credentials()==null||input.credentials().isEmpty()||input.credentials().size()>20||input.credentials().stream().anyMatch(Objects::isNull)||new HashSet<>(input.credentials()).size()!=input.credentials().size()||input.expiresInDays()<1||input.expiresInDays()>30)bad("Selecione até vinte credenciais, destinatário, prazo de 1 a 30 dias e confirme o consentimento.");String recipient=text(input.recipientEmail(),180).toLowerCase(Locale.ROOT),label=text(input.holderLabel(),80);if(!recipient.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))bad("Informe o e-mail empresarial do recrutador autorizado.");jdbc.queryForObject("SELECT id FROM student_users WHERE id=? FOR UPDATE",Long.class,uid);if(jdbc.queryForObject("SELECT count(*) FROM learning_passport_shares WHERE student_id=? AND revoked_at IS NULL AND expires_at>CURRENT_TIMESTAMP",Integer.class,uid)>=100)bad("Revogue compartilhamentos antigos antes de criar outros.");
  var args=new ArrayList<Object>();args.add(uid);args.addAll(input.credentials());String placeholders=String.join(",",Collections.nCopies(input.credentials().size(),"?"));var rows=jdbc.queryForList(select()+" WHERE a.student_id=? AND a.id IN ("+placeholders+") FOR UPDATE OF a",args.toArray());if(rows.size()!=input.credentials().size()||rows.stream().anyMatch(r->!status(r).equals("ACTIVE")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Compartilhe somente credenciais próprias, válidas e comprovadas.");byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO learning_passport_shares(id,student_id,token_hash,recipient_email,holder_label,expires_at) VALUES (?,?,?,?,?,?)",id,uid,RadarBridge.hash(token),recipient,label,java.sql.Timestamp.from(Instant.now().plusSeconds(86400L*input.expiresInDays())));for(UUID award:input.credentials())jdbc.update("INSERT INTO learning_passport_share_items(share_id,award_id) VALUES (?,?)",id,award);audit(uid,id,"PASSPORT_SHARE_CREATED");return Map.of("id",id,"token",token,"expiresInDays",input.expiresInDays());
 }
 public void revokeShare(String email,UUID id){long uid=access.account(email).id();if(jdbc.update("UPDATE learning_passport_shares SET revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP) WHERE id=? AND student_id=?",id,uid)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);audit(uid,id,"PASSPORT_SHARE_REVOKED");}
 public Map<String,Object> verify(String key,Verify input){bridge.authorize(key);if(input==null||input.token()==null||!input.token().matches("[A-Za-z0-9_-]{43}")||input.recipientEmail()==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);var shares=jdbc.queryForList("SELECT s.id,s.student_id,s.holder_label,s.expires_at FROM learning_passport_shares s JOIN student_users u ON u.id=s.student_id AND u.account_status='ACTIVE' AND u.email_verified=TRUE WHERE s.token_hash=? AND LOWER(s.recipient_email)=LOWER(?) AND s.revoked_at IS NULL AND s.expires_at>CURRENT_TIMESTAMP",RadarBridge.hash(input.token()),input.recipientEmail());if(shares.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Compartilhamento indisponível, expirado, revogado ou destinado a outro recrutador.");var share=shares.get(0);var rows=jdbc.queryForList(select()+" JOIN learning_passport_share_items i ON i.award_id=a.id WHERE i.share_id=? AND a.student_id=? ORDER BY a.awarded_at DESC",share.get("id"),share.get("student_id"));var result=new LinkedHashMap<String,Object>();result.put("holderLabel",share.get("holder_label"));result.put("holderLabelVerified",false);result.put("expiresAt",share.get("expires_at"));result.put("credentials",rows.stream().map(r->details(r,status(r).equals("ACTIVE"))).toList());result.put("formalCertificate",false);result.put("notice","Registros internos de aprendizagem. Identificação opcional autodeclarada; não equivale a documento de identidade nem certificado oficial.");audit(((Number)share.get("student_id")).longValue(),(UUID)share.get("id"),"PASSPORT_SHARE_VERIFIED");return result;}
 private void page(int offset,int limit){if(offset<0||offset>10000||limit<1||limit>50)bad("Use páginas de até cinquenta credenciais.");}
 private void audit(long actor,UUID resource,String event){jdbc.update("INSERT INTO learning_assessment_audit(actor_id,resource_id,event) VALUES (?,?,?)",actor,resource,event);}
}
